// GPU perf-per-watt index — record JAH-GPC-GPU-000001
// Property of Justin Addam Higgins (JAH). Deterministic: same inputs, same output.
var m = {"tflops": 90, "vram_gb": 24, "tdp_w": 450};
var value = (m.tflops*m.vram_gb*10/m.tdp_w);
if (!isFinite(value)) { console.log('DEMO_FAIL|JAH-GPC-GPU-000001|non-finite'); process.exit(1); }
console.log('DEMO_OK|JAH-GPC-GPU-000001|' + value.toFixed(2) + ' perf-per-watt index');

